class JwtAuthenticationFilter extends OncePerRequestFilter {

    @Override
    protected void doFilterInternal(HttpServletRequest request, HttpServletResponse response,
                                     FilterChain filterChain) throws IOException, ServletException {
        String header = request.getHeader("Authorization");
        if (header != null && header.startsWith("Bearer ")) {
            String token = header.substring(7);
            try {
                Claims claims = Jwts.parser().verifyWith(key).build()
                        .parseSignedClaims(token).getPayload();
                var authentication = new UsernamePasswordAuthenticationToken(
                        claims.getSubject(), null,
                        List.of(new SimpleGrantedAuthority("ROLE_" + claims.get("role"))));
                SecurityContextHolder.getContext().setAuthentication(authentication);
            } catch (JwtException e) {
                // celowo nic nie robimy - zadanie idzie dalej jako nieuwierzytelnione
            }
        }
        filterChain.doFilter(request, response);
    }
}

@PostMapping("/api/login")
ResponseEntity<String> login(@RequestBody LoginRequest request) {
    String storedHash = passwordHashes.get(request.username());
    if (storedHash == null || !encoder.matches(request.password(), storedHash)) {
        return ResponseEntity.status(401).body("Bledne poswiadczenia");
    }
    String token = Jwts.builder()
            .subject(request.username())
            .claim("role", roles.get(request.username()))
            .expiration(Date.from(Instant.now().plus(Duration.ofHours(1))))
            .signWith(key)
            .compact();
    return ResponseEntity.ok(token);
}

